'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const KEY='kpap-prototype-v1';
const questions=[
 {id:'D001',input:'결제 후 주문을 취소하고 싶어요.',expected:'배송 시작 전에는 주문 내역에서 취소할 수 있습니다.',tag:'주문'},
 {id:'D002',input:'반품 배송비는 얼마인가요?',expected:'단순 변심은 3,000원, 상품 불량은 무료입니다.',tag:'반품'},
 {id:'D003',input:'배송지를 변경할 수 있나요?',expected:'출고 전 주문 내역에서 변경할 수 있습니다.',tag:'배송'},
 {id:'D004',input:'영수증은 어디서 발급하나요?',expected:'결제 내역에서 영수증을 내려받을 수 있습니다.',tag:'결제'},
 {id:'D005',input:'쿠폰을 적용하지 못했어요.',expected:'사용 조건과 유효기간을 확인해주세요.',tag:'쿠폰'},
 {id:'D006',input:'환불은 언제 완료되나요?',expected:'승인 후 영업일 기준 3~5일이 필요합니다.',tag:'환불'}
];
function seed(){
 const config={name:'고객 지원 · 기본',model:'gateway-balanced',prompt:'support-system v12',temperature:'0.2',knowledge:'고객 서비스 가이드',topK:'5',tools:['ticket-search','order-status']};
 return {page:'overview',agent:'support',environment:'staging',config,versions:[{version:3,...clone(config),note:'반품 정책 프롬프트 개선'},{version:2,...clone(config),prompt:'support-system v11',note:'운영 기준'}],active:2,dataset:clone(questions),datasetVersion:4,input:'반품 배송비는 얼마인가요?',scenario:'normal',runs:[
 {id:'RUN-2401',input:questions[1].input,output:questions[1].expected,state:'성공',trace:'complete',scenario:'normal',config:clone(config),version:3,time:'오늘 14:32',source:'운영',score:0.63},
 {id:'RUN-2400',input:questions[0].input,output:'주문 번호를 알려주시면 취소 가능 여부를 확인하겠습니다.',state:'성공',trace:'complete',scenario:'tool-error',config:clone(config),version:2,time:'오늘 14:28',source:'운영',score:0.78},
 {id:'RUN-2399',input:questions[5].input,output:questions[5].expected,state:'성공',trace:'partial',scenario:'trace-delay',config:clone(config),version:2,time:'오늘 14:21',source:'운영',score:null}
 ],experiments:[
 {id:'EXP-042',name:'기준 · 운영 설정',version:2,code:'build-17',datasetVersion:4,model:'gateway-balanced',prompt:'support-system v11',scores:[0.88,0.87,0.79,0.95,0.81,null],status:'부분 실패',results:[]},
 {id:'EXP-043',name:'후보 · 반품 안내 개선',version:3,code:'build-17',datasetVersion:4,model:'gateway-balanced',prompt:'support-system v12',scores:[0.94,0.96,0.63,0.95,0.88,null],status:'부분 실패',results:[]}
 ],policy:{name:'고객 응답 품질',version:2,sample:'10',budget:'50000',threshold:'0.8',evaluator:'답변 관련성 v2',active:true},
 onlinePeriod:'7d',onlineFilter:'all',offlineFilter:'all',selectedExperiment:'EXP-043',baseline:'EXP-042',policyHistory:['v2 · 표본 10% · 활성'],draft:null};
}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}
let executing=false,token=0,latestRun=null,traceNode=0,traceJudge=false,traceRun=null,wizardStep=0,wizard={},datasetDraft=[],importErrors=[],toastTimer;
const navs=[['overview','◫','개요'],['settings','⚙','설정'],['run','▷','실행'],['offline','≋','오프라인 평가'],['online','⌁','온라인 평가']];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
function btn(text,action,cls='',extra=''){return '<button class="btn '+cls+'" data-action="'+action+'" '+extra+'>'+text+'</button>'}
function badge(text,type=''){return '<span class="badge '+type+'">'+esc(text)+'</span>'}
function head(title,sub,actions=''){return '<div class="page-head"><div><div class="eyebrow">AGENT PLAYGROUND / '+esc(state.environment.toUpperCase())+'</div><h1>'+title+'</h1><p>'+sub+'</p></div><div class="head-actions">'+actions+'</div></div>'}
function panel(title,body,action=''){return '<section class="panel"><div class="panel-head"><h2>'+title+'</h2>'+action+'</div>'+body+'</section>'}
function metrics(items){return '<div class="metrics">'+items.map(i=>'<div class="metric"><div class="label">'+i[0]+'</div><strong class="number">'+i[1]+'</strong><small class="'+(i[3]||'')+'">'+i[2]+'</small></div>').join('')+'</div>'}
function option(v,label,selected){return '<option value="'+esc(v)+'" '+(v===selected?'selected':'')+'>'+esc(label)+'</option>'}
function field(label,content,hint=''){const id=content.match(/id="([^"]+)"/);return '<div class="form-field"><label '+(id?'for="'+id[1]+'"':'')+'>'+label+'</label>'+content+(hint?'<p class="hint">'+hint+'</p>':'')+'</div>'}
function chart(){return '<div class="legend"><span>응답 품질</span><span>운영 기준</span></div><svg class="chart" viewBox="0 0 700 190" role="img" aria-label="모의 7일 응답 품질 추세: 0.86, 0.89, 0.88, 0.92, 0.83, 0.91, 0.93"><g fill="none" stroke="#e8eef0"><path d="M38 22H680 M38 66H680 M38 110H680 M38 154H680"/></g><g fill="#8a98a3" font-size="10"><text x="5" y="27">1.0</text><text x="5" y="72">0.9</text><text x="5" y="115">0.8</text><text x="5" y="159">0.7</text></g><path d="M38 102L145 80L252 80L359 66L466 66L573 65L680 66" stroke="#bac9cf" stroke-dasharray="4 5" fill="none" stroke-width="2"/><path d="M38 87L145 70L252 77L359 49L466 107L573 57L680 42" stroke="#087c65" fill="none" stroke-width="2.5"/><g fill="#087c65">'+[[38,87],[145,70],[252,77],[359,49],[466,107],[573,57],[680,42]].map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3.5"/>').join('')+'</g><g fill="#8a98a3" font-size="10">'+[7,8,9,10,11,12,13].map((d,i)=>'<text x="'+(30+i*107)+'" y="185">10/'+d+'</text>').join('')+'</g></svg><details><summary>차트 데이터 보기</summary><p class="muted">10/7 0.86 · 10/8 0.89 · 10/9 0.88 · 10/10 0.92 · 10/11 0.83 · 10/12 0.91 · 10/13 0.93</p></details>'}
function runRows(runs){return '<div class="table-wrap"><table><thead><tr><th>실행 / 입력</th><th>출처</th><th>설정</th><th>결과</th><th>처리 기록</th><th></th></tr></thead><tbody>'+runs.map(r=>'<tr><td><strong>'+esc(r.input)+'</strong><div class="mono">'+r.id+' · '+r.time+'</div></td><td>'+r.source+'</td><td>v'+r.version+'</td><td>'+badge(r.state,r.state==='성공'?'green':r.state==='실패'?'red':'amber')+'</td><td>'+badge(({complete:'수집 완료',partial:'부분 수집',pending:'수집 중',unavailable:'확인 불가'})[r.trace],r.trace==='complete'?'':'amber')+'</td><td>'+btn('상세 보기','run-detail','small','data-id="'+r.id+'"')+'</td></tr>').join('')+'</tbody></table></div>'}
function overview(){
 return head(state.agent==='support'?'고객 지원 에이전트':'사내 지식 에이전트','설정의 효과를 확인하고, 실행과 평가를 같은 문맥에서 조사하세요.',btn('시험 실행','go-run','primary'))+
 '<div class="flow"><button data-action="go-settings">01 설정 후보<span>모델 · 프롬프트 · 도구</span></button><b>→</b><button data-action="go-run">02 시험 실행<span>응답과 처리 과정</span></button><b>→</b><button data-action="go-offline">03 평가 비교<span>회귀 항목 조사</span></button><b>→</b><button data-action="go-online">04 운영 품질<span>문제 사례 환류</span></button></div>'+
 metrics([['운영 활성 설정','v'+state.active,'build-17 · 최근 적용'],['현재 평가 대상',state.dataset.length+'개','회귀 데이터셋 v'+state.datasetVersion],['응답 품질','0.93','모의 7일 추세 · +0.04','positive'],['온라인 평가',state.policy.active?'활성':'중지','정책 v'+state.policy.version+' · 표본 '+state.policy.sample+'%']])+
 '<div class="grid wide">'+panel('운영 품질 추세','<div class="panel-body">'+chart()+'</div>',btn('품질 분석','go-online','small'))+
 panel('현재 실행 설정','<div class="panel-body"><div class="agent-identity"><div class="agent-symbol">◇</div><div><strong>'+esc(state.config.name)+'</strong><p class="muted">A2A · SDK · build-17</p></div></div>'+[['모델',state.config.model],['프롬프트',state.config.prompt],['지식',state.config.knowledge],['허용 도구',state.config.tools.length+'개']].map(i=>'<div class="row"><span class="muted">'+i[0]+'</span><strong>'+esc(i[1])+'</strong></div>').join('')+'<div class="note section-line">설정 저장과 운영 반영은 별도 동작입니다. 기존 실행의 설정은 유지됩니다.</div></div>',btn('설정 편집','go-settings','small'))+'</div>'+
 panel('최근 실행',runRows(state.runs.slice(0,4)),btn('모든 실행','go-run','small'));
}
function configForm(c,prefix='cfg'){
 return '<div class="form-grid">'+field('모델','<select id="'+prefix+'-model" data-config="model">'+['gateway-balanced','gateway-fast','gateway-reasoning'].map(v=>option(v,v,c.model)).join('')+'</select>')+
 field('프롬프트 버전','<select id="'+prefix+'-prompt" data-config="prompt">'+['support-system v12','support-system v11','knowledge-system v4'].map(v=>option(v,v,c.prompt)).join('')+'</select>','phase 대신 실행에 적용할 실제 버전을 확인합니다.')+'</div>'+
 field('지식','<select id="'+prefix+'-knowledge" data-config="knowledge">'+['고객 서비스 가이드','사내 업무 가이드'].map(v=>option(v,v,c.knowledge)).join('')+'</select>')+
 '<div class="form-field"><label>허용 도구</label>'+['ticket-search','order-status','refund-status'].map(v=>'<label class="check-row"><input type="checkbox" data-tool="'+v+'" '+(c.tools.includes(v)?'checked':'')+'> '+v+'</label>').join('')+'</div>'+
 '<details><summary>고급 옵션</summary><div class="form-grid">'+field('Temperature','<input id="'+prefix+'-temperature" data-config="temperature" type="number" min="0" max="2" step="0.1" value="'+esc(c.temperature)+'">')+field('검색 Top K','<input id="'+prefix+'-topK" data-config="topK" type="number" min="1" max="20" value="'+esc(c.topK)+'">')+'</div></details>';
}
function settings(){const c=state.draft||state.config;return head('실행 설정','실행에 사용할 자원과 버전을 고정합니다.',btn('초안으로 시험','test-draft')+btn('새 버전 저장','save-config','primary'))+
 '<div class="grid wide">'+panel('설정 후보','<div class="panel-body">'+field('프로필 이름','<input id="cfg-name" data-config="name" value="'+esc(c.name)+'">')+configForm(c)+'<p id="config-error" class="error-text" role="alert"></p></div>',state.draft?badge('미저장 초안','amber'):badge('저장된 버전','green'))+
 '<div>'+panel('버전과 운영 참조','<div class="panel-body">'+state.versions.map(v=>'<div class="row"><div><strong>v'+v.version+'</strong> '+(state.active===v.version?badge('운영 활성','green'):'')+'<p class="muted">'+esc(v.note)+'<br>'+esc(v.prompt)+'</p></div><div>'+btn('불러오기','load-version','small','data-version="'+v.version+'"')+' '+btn(state.active===v.version?'활성':'운영 적용','apply-version','small','data-version="'+v.version+'" '+(state.active===v.version?'disabled':''))+'</div></div>').join('')+'</div>')+
 panel('적용 규칙','<div class="panel-body"><div class="note">기본값 → 프로필 → 허용 변경 → 검증 → 불변 스냅샷</div><p class="muted">새 버전 저장은 운영 설정을 바꾸지 않습니다. 운영 활성 참조를 변경하면 이후 요청부터 적용됩니다.</p><div class="row"><span>코드 버전</span><span class="mono">build-17</span></div><div class="row"><span>현재 환경</span>'+badge(state.environment)+'</div></div>')+'</div></div>'}
const scenarioNames={normal:'정상 응답', 'tool-error':'도구 오류 후 대체 응답','needs-input':'추가 입력 요청','trace-delay':'처리 기록 수집 지연',unknown:'원격 결과 확인 불가'};
function runPage(){const r=latestRun||state.runs.find(x=>x.source==='시험');if(r)latestRun=r;
 return head('시험 실행','응답과 실제 적용 설정을 먼저 확인하고, 필요한 구간을 조사하세요.',btn('설정 편집','go-settings'))+
 '<div class="grid">'+panel('입력과 설정','<div class="panel-body"><div class="note">'+esc((state.draft||state.config).name)+' · '+esc((state.draft||state.config).prompt)+'<br>'+esc((state.draft||state.config).model)+(state.draft?' · 미저장 초안':'')+'</div>'+field('고객 입력','<textarea id="run-input" rows="5" placeholder="질문을 입력하세요">'+esc(state.input)+'</textarea>')+'<div class="pill-group">'+btn('반품 배송비','sample','small','data-index="1"')+btn('배송지 변경','sample','small','data-index="2"')+'</div>'+field('체험할 시나리오','<select id="scenario">'+Object.entries(scenarioNames).map(([v,n])=>option(v,n,state.scenario)).join('')+'</select>','프로토타입의 정상·예외 상태를 선택합니다.')+'<div class="inline">'+btn(executing?'실행 중…':'실행','execute','primary',executing?'disabled':'')+(executing?btn('취소 요청','cancel-run','danger'):'')+'</div><p id="run-error" class="error-text" role="alert"></p></div>')+
 panel('응답',r?'<div class="panel-body"><div class="inline">'+badge(r.state,r.state==='성공'?'green':r.state==='실패'?'red':'amber')+'<span class="mono">'+r.id+'</span></div><div class="answer">'+esc(r.output)+'</div>'+
 (r.state==='추가 입력 대기'?'<div class="inline"><input id="followup" placeholder="주문 번호를 입력하세요" aria-label="추가 입력">'+btn('추가 입력 보내기','send-input','primary')+'</div>':'')+
 (r.state==='결과 확인 불가'?'<div class="note warning">원격 상태를 확인할 수 없습니다. 새 실행을 만들지 않고 상태를 다시 확인합니다.</div>'+btn('상태 확인','reconcile'):'')+
 '<div class="stat-line"><span>적용 설정 <strong>'+esc(r.config.prompt)+'</strong></span><span>처리시간 <strong>'+(r.state==='성공'?'1.84초':'—')+'</strong></span><span>코드 <strong>build-17</strong></span></div><div class="section-line inline">'+btn('처리 과정 보기','trace','', 'data-id="'+r.id+'"')+btn('실제 설정','snapshot','', 'data-id="'+r.id+'"')+btn('데이터셋 후보','candidate','', 'data-id="'+r.id+'"')+'</div><p class="hint">'+(r.trace==='pending'?(r.state==='성공'?'응답은 완료되었습니다. 처리 기록을 수집하고 있습니다.':'실행과 처리 기록 수집 상태를 확인하고 있습니다.'):r.trace==='partial'?'일부 처리 기록만 확인할 수 있습니다.':'처리 기록 '+(r.trace==='complete'?'수집 완료':'확인 불가'))+'</p></div>':
 '<div class="empty"><div><div class="empty-icon">▷</div><strong>입력으로 에이전트를 시험하세요</strong><p>응답, 적용한 버전, 내부 호출을<br>같은 실행에서 확인할 수 있습니다.</p></div></div>')+'</div>'+
 panel('실행 이력','<div class="toolbar"><span class="muted">시험 · 운영 실행</span>'+btn('목록 내려받기','export-runs','small')+'</div>'+runRows(state.runs));
}
function expResults(e){return e.results.length?e.results:questions.map((q,i)=>({...q,score:e.scores[i],status:e.scores[i]===null?'평가 오류':'평가 완료',output:(e.id==='EXP-043'&&i===2)?'출고 이후에도 배송지를 변경할 수 있습니다.':q.expected,trace:i===5?'partial':'complete'}))}
function avg(e){let a=expResults(e).filter(x=>x.score!==null);return a.length?(a.reduce((s,x)=>s+x.score,0)/a.length).toFixed(2):'—'}
function offline(){const e=state.experiments.find(e=>e.id===state.selectedExperiment)||state.experiments[0];let rows=expResults(e);if(state.offlineFilter==='error')rows=rows.filter(r=>r.score===null);if(state.offlineFilter==='low')rows=rows.filter(r=>r.score!==null&&r.score<.8);
 return head('오프라인 평가','고정된 데이터와 평가 기준으로 변경 전후를 비교합니다.',btn('데이터셋 관리','dataset')+btn('평가 시작','new-experiment','primary'))+
 '<div class="tabs"><button class="active">실험과 비교</button><button data-action="dataset">데이터셋 · v'+state.datasetVersion+'</button><button data-action="evaluator">평가 기준</button></div>'+
 '<div class="grid wide">'+panel('실험 목록','<div class="table-wrap"><table><thead><tr><th>실험</th><th>설정</th><th>평균 점수</th><th>상태</th><th></th></tr></thead><tbody>'+state.experiments.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong><div class="mono">'+x.id+' · 데이터 v'+x.datasetVersion+'</div></td><td>v'+x.version+'</td><td class="number">'+avg(x)+'</td><td>'+badge(x.status,x.status==='부분 실패'?'amber':'green')+'</td><td>'+btn('선택','select-experiment','small','data-id="'+x.id+'"')+'</td></tr>').join('')+'</tbody></table></div>')+
 panel('기준과 후보 비교','<div class="panel-body">'+field('기준 실험','<select id="baseline">'+state.experiments.map(x=>option(x.id,x.name,state.baseline)).join('')+'</select>')+field('후보 실험','<select id="candidate-experiment">'+state.experiments.map(x=>option(x.id,x.name,e.id)).join('')+'</select>')+btn('비교 결과 열기','compare','primary')+'<p class="hint">같은 입력·반복·평가기 버전의 유효 쌍만 비교합니다.</p></div>')+'</div>'+
 metrics([['유효 평균',avg(e),'답변 품질 v2 · 0–1'],['유효 평가',expResults(e).filter(r=>r.score!==null).length+' / '+expResults(e).length,'평가 오류는 0점과 구분'],['업무 지연','1.84초','모의 p50'],['업무 / 평가 비용','₩124 / ₩32','모의 알려진 비용']])+
 panel('항목 결과 · '+esc(e.name),(e.status==='실행 중'?'<div class="panel-body"><div class="progress-track"><span style="width:'+Math.round((e.progress||0)*100)+'%"></span></div><div class="inline"><span class="muted">완료 '+Math.round((e.progress||0)*e.results.length)+' / '+e.results.length+'</span>'+btn('실험 중단','stop-experiment','small danger','data-id="'+e.id+'"')+'</div></div>':'')+'<div class="toolbar"><span class="muted">'+esc(e.prompt)+' · '+e.code+'</span><select id="offline-filter" aria-label="항목 필터">'+option('all','전체 항목',state.offlineFilter)+option('low','낮은 점수',state.offlineFilter)+option('error','평가 오류',state.offlineFilter)+'</select></div><div class="table-wrap"><table><thead><tr><th>항목 / 입력</th><th>유효 점수</th><th>평가</th><th>처리 기록</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+esc(r.input)+'</strong><div class="mono">'+r.id+' · '+esc(r.tag)+'</div></td><td class="number">'+(r.score===null?'—':r.score.toFixed(2))+'</td><td>'+badge(r.status,r.score===null?'amber':r.score<.8?'red':'green')+'</td><td>'+badge(({pending:'수집 중',partial:'부분 수집',complete:'수집 완료',unavailable:'확인 불가'})[r.trace]||'수집 대기')+'</td><td>'+btn('근거와 처리 과정','eval-detail','small','data-id="'+r.id+'" data-exp="'+e.id+'"')+'</td></tr>').join('')+'</tbody></table></div>');
}
function online(){const production=state.runs.filter(r=>r.source==='운영'),valid=production.filter(r=>r.score!==null),passed=valid.filter(r=>r.score>=Number(state.policy.threshold));let rows=state.runs.filter(r=>r.source==='운영');if(state.onlineFilter==='low')rows=rows.filter(r=>r.score!==null&&r.score<Number(state.policy.threshold));if(state.onlineFilter==='missing')rows=rows.filter(r=>r.score===null);
 return head('온라인 평가','운영 응답 완료 후 품질을 평가하고 문제 사례를 조사합니다.',btn('정책 편집','policy')+btn(state.policy.active?'정책 중지':'정책 활성화','toggle-policy','primary'))+
 '<div class="note">정책 v'+state.policy.version+' · '+esc(state.policy.evaluator)+' · 표본 '+state.policy.sample+'% · 일 예산 ₩'+Number(state.policy.budget).toLocaleString()+' '+badge(state.policy.active?'활성':'중지',state.policy.active?'green':'amber')+'</div>'+
 metrics([['유효 평가 커버리지',valid.length+' / '+production.length,'모의 대상 실행 3개'],['품질 통과율',valid.length?Math.round(passed.length/valid.length*100)+'%':'—','유효 판정 '+valid.length+'개 · 기준 '+state.policy.threshold],['평가 처리 지연','4.2초','업무 완료 → 평가 완료'],['평가 제외',(production.length-valid.length)+'개','필수 관측 수집 대기']])+
 '<div class="grid wide">'+panel('품질 추세','<div class="panel-body">'+chart()+'</div>','<select id="online-period" aria-label="조회 기간">'+option('7d','최근 7일',state.onlinePeriod)+option('today','오늘',state.onlinePeriod)+'</select>')+
 panel('평가 처리 상태','<div class="panel-body">'+[['대상 운영 실행',production.length+'개'],['표본 선택',production.length+'개 (데모 고정 사례)'],['유효 평가',valid.length+'개'],['필수 관측 대기',(production.length-valid.length)+'개'],['정책 버전','v'+state.policy.version]].map(x=>'<div class="row"><span class="muted">'+x[0]+'</span><strong>'+x[1]+'</strong></div>').join('')+'<p class="hint">추세는 별도 모의 데이터입니다. 평가 오류·제외는 품질 점수에 포함하지 않습니다.</p></div>')+'</div>'+
 panel('조사할 운영 사례','<div class="toolbar"><span class="muted">답변 품질 → 근거 → 업무·평가 처리 과정</span><select id="online-filter" aria-label="운영 사례 필터">'+option('all','전체 사례',state.onlineFilter)+option('low','기준 미달',state.onlineFilter)+option('missing','평가 대기·제외',state.onlineFilter)+'</select></div><div class="table-wrap"><table><thead><tr><th>고객 입력</th><th>설정</th><th>유효 점수</th><th>상태</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+esc(r.input)+'</strong><div class="mono">'+r.id+' · '+r.time+'</div></td><td>v'+r.version+'</td><td>'+(r.score===null?'—':r.score.toFixed(2))+'</td><td>'+badge(r.score===null?'평가 대기':r.score<Number(state.policy.threshold)?'기준 미달':'통과',r.score===null?'amber':r.score<Number(state.policy.threshold)?'red':'green')+'</td><td>'+btn('사례 조사','run-detail','small','data-id="'+r.id+'"')+'</td></tr>').join('')+'</tbody></table></div>');
}
function render(focus=false){persist();$('#nav').innerHTML=navs.map(([id,icon,label])=>'<a href="#'+id+'" class="'+(state.page===id?'active':'')+'" '+(state.page===id?'aria-current="page"':'')+' aria-label="'+label+'"><span class="nav-icon" aria-hidden="true">'+icon+'</span><span class="nav-text">'+label+'</span></a>').join('');$('#agent-label').textContent=state.agent==='support'?'고객 지원 에이전트':'사내 지식 에이전트';$('#agent-select').value=state.agent;$('#environment').value=state.environment;$('#main').innerHTML=({overview,settings,run:runPage,offline,online})[state.page]();if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0)}}
function go(page){if(!navs.some(x=>x[0]===page))page='overview';state.page=page;if(location.hash!=='#'+page)location.hash=page;else render(true)}
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'overview';if(!navs.some(x=>x[0]===state.page))state.page='overview';render(true)});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function modal(title,sub,content,actions='',wide=false){$('#modal').className=wide?'dialog-wide':'';$('#modal-content').innerHTML='<div class="dialog-top"><div><h2>'+title+'</h2><p class="muted">'+sub+'</p></div><button class="dialog-close" data-action="close-modal" aria-label="닫기">×</button></div>'+content+(actions?'<div class="dialog-actions">'+actions+'</div>':'');if(!$('#modal').open)$('#modal').showModal()}
function close(){ $('#modal').close()}
function findRun(id){return state.runs.find(r=>r.id===id)}
function makeRun(input,config,scenario,source='시험'){return {id:'RUN-'+Date.now().toString().slice(-6),input,config:clone(config),version:state.versions[0].version,scenario,source,time:'방금',state:'설정 적용 대기',output:'설정 스냅샷과 자원 권한을 확인하고 있습니다.',trace:'pending',score:null}}
function execute(){
 const input=$('#run-input').value.trim();if(!input){$('#run-error').textContent='고객 입력을 작성하세요.';$('#run-input').focus();return}
 state.input=input;state.scenario=$('#scenario').value;const r=makeRun(input,state.draft||state.config,state.scenario);latestRun=r;state.runs.unshift(r);executing=true;const t=++token;render();
 setTimeout(()=>{if(token!==t)return;r.state='실행 중';r.output='검색 근거와 도구 결과를 확인하고 있습니다.';if(state.page==='run')render()},650);
 setTimeout(()=>{if(token!==t)return;executing=false;
 if(r.scenario==='needs-input'){r.state='추가 입력 대기';r.output='주문 상태를 확인하려면 주문 번호가 필요합니다. 주문 번호를 입력해주세요.';r.trace='complete'}
 else if(r.scenario==='unknown'){r.state='결과 확인 불가';r.output='요청 제한시간을 넘겼습니다. 원격 실행 결과를 확인할 수 없습니다.';r.trace='unavailable'}
 else{r.state='성공';r.output=r.scenario==='tool-error'?'주문 조회 도구에 일시적인 오류가 있습니다. 배송 시작 전에는 주문 내역에서 취소할 수 있습니다. 주문 상태는 잠시 후 다시 확인해주세요.':r.input.includes('배송지')?'출고 전에는 주문 내역에서 배송지를 변경할 수 있습니다. 출고 후에는 고객센터에 문의해주세요.':r.input.includes('반품')?'단순 변심 반품의 배송비는 3,000원입니다. 상품 불량이나 오배송인 경우 배송비는 무료입니다.\n\n반품 접수는 주문 내역에서 진행할 수 있습니다.': '고객 서비스 가이드에 따라 안내드립니다. 주문 내역에서 요청 상태를 확인하고, 추가 도움이 필요하면 고객센터에 문의해주세요.';r.trace=r.scenario==='trace-delay'?'pending':'complete'}
 persist();if(state.page==='run')render();toast('모의 실행이 완료되었습니다.');
 if(r.trace==='pending')setTimeout(()=>{r.trace='partial';persist();if(state.page==='run')render()},2300);
 },1800);
}
function snapshot(r){modal('실제 적용 설정','요청 시작에 고정한 설정입니다. 기존 실행 중에는 변경하지 않습니다.','<div class="code">'+esc(JSON.stringify({run_id:r.id,config_snapshot_id:'snapshot-'+r.id,agent_version:'build-17',model:r.config.model,prompt:r.config.prompt,tools:r.config.tools,knowledge:r.config.knowledge,temperature:r.config.temperature},null,2))+'</div>',btn('닫기','close-modal'))}
function nodes(r,judge=false){if(judge)return [{name:'평가 실행',time:520,type:'EVALUATION',input:r.input,output:'답변 품질 0.63 · 근거 확인 필요',desc:'답변 품질 v2 · 평가 비용 ₩4',start:0},{name:'Judge 모델',time:460,type:'GENERATION',input:'입력과 응답을 루브릭에 따라 평가. 업무 도구 접근 없음.',output:'반품 조건에 대한 근거를 충분히 설명하지 못했습니다.',desc:'평가용 모델 · rubric v2',start:30}];return [
 {name:'에이전트 실행',time:1840,type:'AGENT',input:r.input,output:r.output,desc:r.id+' · build-17',start:0},
 {name:'지식 검색',time:186,type:'RETRIEVER',input:r.input,output:'고객 서비스 가이드 / 반품 정책 §2\n단순 변심 3,000원 · 불량/오배송 무료',desc:r.config.knowledge+' · Top K '+r.config.topK,start:40},
 {name:'ticket-search',time:r.scenario==='tool-error'?420:220,type:'TOOL',input:'{"query": "'+r.input+'"}',output:r.scenario==='tool-error'?'UPSTREAM_ERROR · 첫 시도 503 · 재시도 503\n최종 실패 → 가이드 기반 대체 응답':'관련 문의 3건을 찾았습니다.',desc:r.scenario==='tool-error'?'논리적 호출 1 · 실제 시도 2':'논리적 호출 1 · 실제 시도 1',start:240},
 {name:'모델 응답',time:1120,type:'GENERATION',input:'프롬프트 '+r.config.prompt+'\n고객 입력과 검색 근거',output:r.output,desc:r.config.model+' · 입력 412 / 출력 138 tokens',start:690}
 ]}
function trace(r,judge=false,node=0){traceRun=r;traceJudge=judge;traceNode=node;const ns=nodes(r,judge);const n=ns[node]||ns[0];
 modal('처리 과정',r.id+' · '+(judge?'평가기 처리':'업무 실행')+' · Langfuse v3 연동 화면의 모의 데이터',
 '<div class="tabs"><button class="'+(!judge?'active':'')+'" data-action="trace-business">업무 처리</button><button class="'+(judge?'active':'')+'" data-action="trace-judge">평가기 처리</button></div>'+
 (r.trace!=='complete'?'<div class="note warning">일부 처리 기록을 수집 중입니다. 아래 구간은 체험용 관측입니다.</div>':'')+
 '<div class="trace-layout"><div class="trace-tree">'+ns.map((x,i)=>'<button class="trace-node '+(i===node?'active':'')+' '+(i?'child':'')+'" data-action="trace-node" data-index="'+i+'">'+esc(x.name)+'<small>'+x.type+' · '+x.time+'ms</small></button>').join('')+'</div><div><div class="inline"><strong>'+esc(n.name)+'</strong>'+badge(n.type,n.name==='ticket-search'&&r.scenario==='tool-error'?'red':'green')+'</div><p class="muted">'+esc(n.desc)+'</p><div class="timeline"><span style="width:'+Math.max(10,n.time/18.4)+'%"></span></div><p class="mini-label">입력</p><div class="code">'+esc(n.input)+'</div><p class="mini-label section-line">출력 / 근거</p><div class="code">'+esc(n.output)+'</div><div class="stat-line"><span>지연 <strong>'+n.time+'ms</strong></span><span>수집 <strong>'+ (r.trace==='complete'?'완료':'부분')+'</strong></span><span>비용 <strong>'+(judge?'₩4':'₩8 (모의)')+'</strong></span></div></div></div>',
 btn('실제 설정','snapshot','', 'data-id="'+r.id+'"')+btn('닫기','close-modal'),true)}
function runDetail(r){modal('실행 상세',r.id+' · '+r.source+' · '+r.time,
 '<div class="grid"><div><div class="subheading">고객 입력</div><div class="prompt">'+esc(r.input)+'</div><div class="subheading section-line">응답</div><div class="answer">'+esc(r.output)+'</div></div><div><div class="row"><span>업무 결과</span>'+badge(r.state,'green')+'</div><div class="row"><span>설정</span><strong>v'+r.version+' · '+esc(r.config.prompt)+'</strong></div><div class="row"><span>품질 평가</span>'+badge(r.score===null?'평가 대기':r.score.toFixed(2),r.score===null?'amber':'red')+'</div><div class="section-line"><strong>평가 근거</strong><p class="muted">'+(r.score===null?'필수 관측 수집을 기다리고 있습니다. 대기는 낮은 점수와 다릅니다.':'입력에 필요한 정책 조건을 응답이 충분히 설명했는지 검토가 필요합니다. 이 근거는 체험용 데이터입니다.')+'</p></div><details><summary>수동 검토</summary><select id="review-verdict"><option>검토 필요</option><option>통과</option><option>미흡</option></select><textarea id="review-reason" rows="2" placeholder="검토 근거를 입력하세요"></textarea>'+btn('검토 저장','save-review','small','data-id="'+r.id+'"')+'</details></div></div>',
 btn('업무 처리 과정','trace','', 'data-id="'+r.id+'"')+btn('평가기 처리','judge','', 'data-id="'+r.id+'"')+btn('데이터셋에 추가','candidate','primary','data-id="'+r.id+'"'),true)}
function candidate(r){modal('데이터셋 후보 검토','운영 응답과 평가 점수를 정답으로 자동 확정하지 않습니다.',
 field('업무 입력','<textarea id="candidate-input" rows="3">'+esc(r.input)+'</textarea>')+field('기대 응답 / 판정 기준','<textarea id="candidate-expected" rows="3" placeholder="검토한 정답이나 기준을 작성하세요"></textarea>')+field('태그','<input id="candidate-tag" value="운영 회귀">')+'<div class="note">원본 '+r.id+'와 연결합니다. 새 버전으로 추가하며 이전 실험 데이터는 유지됩니다.</div><p id="candidate-error" class="error-text" role="alert"></p>',
 btn('취소','close-modal')+btn('새 데이터 버전에 추가','save-candidate','primary','data-id="'+r.id+'"'))}
function dataset(){datasetDraft=clone(state.dataset);importErrors=[];datasetView()}
function datasetView(){modal('평가 데이터셋','고객 지원 회귀 · 발행 v'+state.datasetVersion+' · '+datasetDraft.length+'개 항목',
 '<div class="toolbar"><span class="muted">입력과 기대 응답은 분리합니다.</span><div class="inline"><label class="btn small" style="margin:0">JSONL 가져오기<input id="dataset-import" type="file" accept=".jsonl,.json,.txt" class="sr-only"></label>'+btn('항목 추가','dataset-add','small')+'</div></div>'+
 '<div class="table-wrap"><table><thead><tr><th>고객 입력</th><th>기대 응답</th><th>태그</th><th></th></tr></thead><tbody>'+datasetDraft.map((d,i)=>'<tr><td><input data-dataset="'+i+'" data-key="input" value="'+esc(d.input)+'" aria-label="항목 '+(i+1)+' 입력"></td><td><input data-dataset="'+i+'" data-key="expected" value="'+esc(d.expected)+'" aria-label="항목 '+(i+1)+' 기대 응답"></td><td><input data-dataset="'+i+'" data-key="tag" value="'+esc(d.tag)+'" aria-label="태그" style="min-width:70px"></td><td>'+btn('삭제','dataset-remove','small danger','data-index="'+i+'"')+'</td></tr>').join('')+'</tbody></table></div><p class="hint">JSONL: {"input":"질문","expected_output":"기대 응답","metadata":{"tag":"분류"}}</p><p class="error-text" role="alert">'+esc(importErrors.join(' / '))+'</p>',
 btn('취소','close-modal')+btn('검증하고 새 버전 발행','dataset-publish','primary'),true)}
function newExperiment(){wizardStep=0;wizard={name:'설정 후보 회귀 검증',version:state.versions[0].version,mode:'platform',repetitions:'1',concurrency:'2',criterion:'답변 품질 v2',datasetVersion:state.datasetVersion};wizardView()}
function wizardView(){
 const titles=['설정','데이터','평가 기준','실행 검토'];let body='';
 if(wizardStep===0)body=field('실험 이름','<input id="wiz-name" value="'+esc(wizard.name)+'">')+field('설정 버전','<select id="wiz-version">'+state.versions.map(v=>option(String(v.version),'v'+v.version+' · '+v.prompt,String(wizard.version))).join('')+'</select>')+'<div class="note">코드 build-17 · '+esc(state.config.model)+'<br>실행 시작에 실제 설정 스냅샷을 고정합니다.</div>';
 if(wizardStep===1)body='<div class="note">고객 지원 회귀 · v'+state.datasetVersion+' · '+state.dataset.length+'개 항목</div><p class="muted">정답이 있는 항목 '+state.dataset.filter(d=>d.expected).length+'개. 정답은 에이전트에 전달하지 않습니다.</p>'+btn('데이터셋 확인','wizard-dataset');
 if(wizardStep===2)body=field('평가기','<select id="wiz-criterion">'+option('답변 품질 v2','답변 품질 v2',wizard.criterion)+option('근거 일치 v1','근거 일치 v1',wizard.criterion)+'</select>')+'<div class="note">척도 0–1 · 통과 기준 0.8<br>평가 오류와 제외는 품질 점수에 포함하지 않습니다.</div>'+field('실행 위치','<select id="wiz-mode">'+option('platform','플랫폼 A2A 실행',wizard.mode)+option('local','로컬 개발 worker',wizard.mode)+'</select>')+'<div class="form-grid">'+field('반복','<input id="wiz-repetitions" type="number" min="1" max="3" value="'+wizard.repetitions+'">')+field('병렬도','<input id="wiz-concurrency" type="number" min="1" max="5" value="'+wizard.concurrency+'">')+'</div>';
 if(wizardStep===3)body='<div class="prompt"><strong>'+esc(wizard.name)+'</strong><p>설정 v'+wizard.version+' · 데이터 v'+state.datasetVersion+' · build-17</p><p>'+esc(wizard.criterion)+' · '+(wizard.mode==='local'?'로컬 worker':'플랫폼 A2A')+'</p><p>반복 '+wizard.repetitions+' · 병렬도 '+wizard.concurrency+'</p></div><div class="note section-line">모의 평가를 실행합니다. '+(wizard.mode==='local'?'실제 CLI 연결 없이 worker 진행을 재현합니다.':'실제 모델·도구를 호출하지 않습니다.')+'</div>';
 modal('새 오프라인 평가','조건을 고정하고 기존 결과와 비교합니다.','<div class="steps">'+titles.map((t,i)=>'<div class="step '+(i<=wizardStep?'active':'')+'">'+(i+1)+'. '+t+'</div>').join('')+'</div>'+body+'<p id="wizard-error" class="error-text" role="alert"></p>',
 (wizardStep?btn('이전','wizard-prev'):'')+btn('취소','close-modal')+btn(wizardStep===3?'모의 평가 시작':'다음','wizard-next','primary'));
}
function captureWizard(){if(wizardStep===0){wizard.name=$('#wiz-name').value.trim();wizard.version=Number($('#wiz-version').value)}if(wizardStep===2){wizard.criterion=$('#wiz-criterion').value;wizard.mode=$('#wiz-mode').value;wizard.repetitions=$('#wiz-repetitions').value;wizard.concurrency=$('#wiz-concurrency').value}}
function startExperiment(){close();const v=state.versions.find(v=>v.version===wizard.version);const e={id:'EXP-'+Date.now().toString().slice(-5),name:wizard.name,version:wizard.version,code:'build-17',datasetVersion:state.datasetVersion,model:v.model,prompt:v.prompt,evaluator:wizard.criterion,status:'실행 중',scores:[],results:Array.from({length:Number(wizard.repetitions)},(_,rep)=>clone(state.dataset).map(d=>({...d,id:rep?d.id+'-R'+(rep+1):d.id,repetition:rep+1,score:null,status:'대기',output:'',trace:'pending'}))).flat(),progress:0};state.experiments.unshift(e);state.selectedExperiment=e.id;go('offline');
 const total=e.results.length;let i=0;function tick(){if(e.status!=='실행 중')return;if(i<total){const d=e.results[i];d.score=i===total-1?null:Math.max(.6,.95-i*.04);d.status=d.score===null?'평가 오류':'평가 완료';d.output=d.expected;d.trace=d.score===null?'partial':'complete';i++;e.progress=i/total;persist();if(state.page==='offline')render();setTimeout(tick,400)}else{e.status='부분 실패';persist();render();toast('모의 실험 완료 · 평가 오류 1개는 별도 표시합니다.')}}setTimeout(tick,500)}
function evalRun(e,r){return {id:e.id+'-'+r.id,input:r.input,output:r.output||r.expected,state:'성공',trace:r.trace,scenario:'normal',config:{...state.config,prompt:e.prompt,model:e.model},version:e.version,source:'오프라인',time:'방금',score:r.score}}
function evalDetail(e,r){const run=evalRun(e,r);if(!findRun(run.id))state.runs.push(run);modal('평가 항목 조사',r.id+' · '+e.id+' · '+e.prompt,
 '<div class="grid"><div><div class="subheading">입력</div><div class="prompt">'+esc(r.input)+'</div><div class="subheading section-line">기대 응답</div><div class="prompt">'+esc(r.expected)+'</div></div><div><div class="subheading">에이전트 응답</div><div class="compare-output">'+esc(r.output||r.expected)+'</div><div class="row"><span>품질 점수</span>'+badge(r.score===null?'평가 오류':r.score.toFixed(2),r.score===null?'amber':r.score<.8?'red':'green')+'</div><p class="muted">'+(r.score===null?'Judge 일시 오류로 평가하지 못했습니다. 업무 실행 실패나 0점이 아닙니다.':'정책 근거와 고객 질문의 관련성을 확인했습니다. 이 판단은 모의 평가 결과입니다.')+'</p></div></div>',
 btn('업무 처리','trace','','data-id="'+run.id+'"')+btn('평가기 처리','judge','','data-id="'+run.id+'"')+btn('닫기','close-modal'),true)}
function compare(){
 const a=state.experiments.find(x=>x.id===$('#baseline').value),b=state.experiments.find(x=>x.id===$('#candidate-experiment').value);if(a.id===b.id){toast('서로 다른 기준과 후보를 선택하세요.');return}
 state.baseline=a.id;state.selectedExperiment=b.id;if((a.evaluator||'답변 품질 v2')!==(b.evaluator||'답변 품질 v2')){toast('평가기 버전이 달라 점수를 직접 비교할 수 없습니다.');return}const ar=expResults(a),br=expResults(b);const pairs=br.map(x=>({b:x,a:ar.find(y=>y.id===x.id&&y.input===x.input)})).filter(x=>x.a);const valid=pairs.filter(x=>x.a.score!==null&&x.b.score!==null);
 modal('기준과 후보 비교',a.id+' → '+b.id+' · 답변 품질 v2 · 유효 쌍 '+valid.length+'개',
 '<div class="note">프롬프트 '+esc(a.prompt)+' → '+esc(b.prompt)+' · 데이터 v'+a.datasetVersion+' / v'+b.datasetVersion+'<br>입력이 바뀐 항목과 평가 오류는 점수 차이에서 제외합니다.</div><div class="table-wrap"><table><thead><tr><th>항목</th><th>기준</th><th>후보</th><th>변화</th><th></th></tr></thead><tbody>'+pairs.map(({a:x,b:y})=>{const valid=x.score!==null&&y.score!==null,delta=valid?y.score-x.score:null;return '<tr><td>'+esc(y.input)+'</td><td>'+(x.score===null?'—':x.score.toFixed(2))+'</td><td>'+(y.score===null?'—':y.score.toFixed(2))+'</td><td>'+badge(!valid?'비교 불가':delta<-.01?'회귀 '+delta.toFixed(2):delta>.01?'개선 +'+delta.toFixed(2):'변화 없음',!valid?'amber':delta<-.01?'red':'green')+'</td><td>'+btn('응답 비교','compare-item','small','data-a="'+state.baseline+'" data-b="'+b.id+'" data-id="'+y.id+'"')+'</td></tr>'}).join('')+'</tbody></table></div>',btn('닫기','close-modal'),true);
}
function compareItem(a,b,id){const x=expResults(a).find(r=>r.id===id),y=expResults(b).find(r=>r.id===id);const ra=evalRun(a,x),rb=evalRun(b,y);[ra,rb].forEach(r=>{if(!findRun(r.id))state.runs.push(r)});
 modal('응답과 근거 비교',esc(x.input),'<div class="grid"><div><div class="subheading">기준 · '+a.id+' · '+(x.score===null?'평가 오류':x.score.toFixed(2))+'</div><div class="compare-output">'+esc(x.output||x.expected)+'</div><p class="muted">'+esc(a.prompt)+'</p>'+btn('기준 처리 과정','trace','','data-id="'+ra.id+'"')+'</div><div><div class="subheading">후보 · '+b.id+' · '+(y.score===null?'평가 오류':y.score.toFixed(2))+'</div><div class="compare-output">'+esc(y.output||y.expected)+'</div><p class="muted">'+esc(b.prompt)+'</p>'+btn('후보 처리 과정','trace','','data-id="'+rb.id+'"')+'</div></div><div class="note section-line">기대 응답: '+esc(x.expected)+'<br>평가 근거: 배송 시작 전후 조건이 정확한지 검토합니다. 관측 차이는 원인 판단의 근거이며 자동 결론이 아닙니다.</div>',btn('후보 평가기 처리','judge','','data-id="'+rb.id+'"')+btn('닫기','close-modal'),true)}
function policy(){modal('온라인 평가 정책','시험과 운영 활성화를 분리합니다.',
 field('정책 이름','<input id="policy-name" value="'+esc(state.policy.name)+'">')+field('평가기','<select id="policy-evaluator"><option>답변 관련성 v2</option><option>근거 일치 v1</option></select>')+
 '<div class="form-grid">'+field('표본 비율 (%)','<input id="policy-sample" type="number" min="1" max="100" value="'+state.policy.sample+'">')+field('일 평가 예산 (원)','<input id="policy-budget" type="number" min="100" value="'+state.policy.budget+'">')+field('통과 기준 (0–1)','<input id="policy-threshold" type="number" min="0" max="1" step="0.1" value="'+state.policy.threshold+'">')+'</div><div class="note">대상: Production · 고객 지원 에이전트 · 성공 응답<br>업무 응답 완료 후 비동기 실행 · 정책 시험은 운영 집계에서 제외</div><p id="policy-error" class="error-text" role="alert"></p><details><summary>정책 변경 이력</summary><p class="muted">'+state.policyHistory.map(esc).join('<br>')+'</p></details>',
 btn('정책 시험','preview-policy')+btn('새 버전 저장','save-policy','primary'))}
function readPolicy(){return {name:$('#policy-name').value.trim(),evaluator:$('#policy-evaluator').value,sample:$('#policy-sample').value,budget:$('#policy-budget').value,threshold:$('#policy-threshold').value}}
function validatePolicy(p){return p.name&&Number(p.sample)>=1&&Number(p.sample)<=100&&Number(p.budget)>=100&&Number(p.threshold)>=0&&Number(p.threshold)<=1}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.addEventListener('input',e=>{const x=e.target;if(x.matches('[data-config]')){state.draft=clone(state.draft||state.config);state.draft[x.dataset.config]=x.value;persist()}if(x.id==='run-input'){state.input=x.value;persist()}if(x.matches('[data-dataset]'))datasetDraft[Number(x.dataset.dataset)][x.dataset.key]=x.value});
document.addEventListener('change',async e=>{const x=e.target;
 if(x.id==='environment'){state.environment=x.value;render();toast('환경 문맥을 변경했습니다. 데이터는 모의 데이터입니다.')}
 if(x.id==='agent-select'){state.agent=x.value;render();toast('에이전트 문맥을 변경했습니다. 공통 시나리오 데이터를 사용합니다.')}
 if(x.dataset.tool){state.draft=clone(state.draft||state.config);const set=new Set(state.draft.tools);x.checked?set.add(x.dataset.tool):set.delete(x.dataset.tool);state.draft.tools=[...set];persist()}
 if(x.id==='scenario'){state.scenario=x.value;persist()}
 if(x.id==='offline-filter'){state.offlineFilter=x.value;render()}
 if(x.id==='online-filter'){state.onlineFilter=x.value;render()}
 if(x.id==='online-period'){state.onlinePeriod=x.value;render();toast(x.value==='today'?'오늘의 사례 목록을 표시합니다. 추세는 7일 모의 데이터입니다.':'7일 모의 추세를 표시합니다.')}
 if(x.id==='dataset-import'&&x.files[0]){const text=await x.files[0].text();let items=[];importErrors=[];text.split(/\r?\n/).filter(l=>l.trim()).forEach((line,i)=>{try{const d=JSON.parse(line);if(typeof d.input!=='string'||!d.input.trim())throw Error('input 문자열 필요');items.push({id:'IMPORT-'+Date.now()+'-'+i,input:d.input,expected:d.expected_output||'',tag:d.metadata?.tag||'가져오기'})}catch(err){importErrors.push((i+1)+'행: '+err.message)}});if(!importErrors.length)datasetDraft.push(...items);datasetView()}
});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const act=target.dataset.action,id=target.dataset.id;
 if(act.startsWith('go-')){go(act.slice(3));return}
 switch(act){
 case 'close-modal':close();break;
 case 'reset':modal('데모 초기화','이 브라우저에서 만든 설정·실험·데이터를 초기값으로 되돌립니다.','',btn('취소','close-modal')+btn('초기화','confirm-reset','danger'));break;
 case 'confirm-reset':token++;executing=false;latestRun=null;state=seed();close();location.hash='#overview';render();toast('데모를 초기화했습니다.');break;
 case 'sample':state.input=questions[Number(target.dataset.index)].input;render();break;
 case 'execute':execute();break;
 case 'cancel-run':token++;executing=false;if(latestRun){latestRun.state='취소 요청 중';latestRun.output='런타임의 취소 확인을 기다리고 있습니다.';render();setTimeout(()=>{latestRun.state='취소';latestRun.output='모의 실행을 취소했습니다.';latestRun.trace='partial';persist();if(state.page==='run')render()},450)}break;
 case 'send-input':{const value=$('#followup').value.trim();if(!value){toast('주문 번호를 입력하세요.');return}latestRun.state='성공';latestRun.output='주문 '+value+'는 출고 전입니다. 주문 내역에서 취소할 수 있습니다.';latestRun.followup=value;render();toast('같은 실행의 추가 입력을 처리했습니다.');break}
 case 'reconcile':latestRun.state='성공';latestRun.output='기존 원격 실행의 완료를 확인했습니다. 새 실행은 만들지 않았습니다.';latestRun.trace='complete';render();break;
 case 'run-detail':runDetail(findRun(id));break;
 case 'trace':trace(findRun(id));break;
 case 'judge':trace(findRun(id),true);break;
 case 'trace-business':trace(traceRun,false);break;
 case 'trace-judge':trace(traceRun,true);break;
 case 'trace-node':trace(traceRun,traceJudge,Number(target.dataset.index));break;
 case 'snapshot':snapshot(findRun(id));break;
 case 'candidate':candidate(findRun(id));break;
 case 'save-candidate':{const input=$('#candidate-input').value.trim(),expected=$('#candidate-expected').value.trim();if(!input||!expected){$('#candidate-error').textContent='입력과 검토한 기대 응답을 작성하세요.';return}if(state.dataset.some(d=>d.input===input&&d.expected===expected)){toast('같은 입력과 기대 응답의 항목이 이미 있습니다.');return}state.dataset.push({id:'D'+Date.now().toString().slice(-5),input,expected,tag:$('#candidate-tag').value||'운영 회귀',sourceRun:id});state.datasetVersion++;close();render();toast('데이터셋 v'+state.datasetVersion+'에 검토한 사례를 추가했습니다.');break}
 case 'save-review':{const r=findRun(id);r.review={verdict:$('#review-verdict').value,reason:$('#review-reason').value};persist();toast('수동 검토를 저장했습니다. 자동 점수는 유지합니다.');break}
 case 'save-config':{const c=state.draft||state.config;if(!c.name.trim()||Number(c.temperature)<0||Number(c.temperature)>2||Number(c.topK)<1||Number(c.topK)>20){$('#config-error').textContent='프로필 이름과 옵션 범위를 확인하세요.';return}const v=state.versions[0].version+1;state.versions.unshift({version:v,...clone(c),note:'사용자 설정 변경'});state.config=clone(c);state.draft=null;render();toast('설정 v'+v+' 저장 · 운영 활성 참조는 v'+state.active+'입니다.');break}
 case 'test-draft':go('run');toast('선택한 설정을 시험 실행에 연결했습니다.');break;
 case 'load-version':{const v=state.versions.find(v=>v.version===Number(target.dataset.version));state.draft=clone(v);delete state.draft.version;delete state.draft.note;render();toast('v'+v.version+'을 편집 초안으로 불러왔습니다.');break}
 case 'apply-version':{const v=Number(target.dataset.version);modal('운영 설정 적용','저장과 운영 반영은 별도 동작입니다.','<div class="note">활성 참조 v'+state.active+' → v'+v+'<br>이후 요청부터 적용합니다. 기존 실행은 이전 설정을 유지합니다.<br>프로토타입에서는 실제 운영 환경을 변경하지 않습니다.</div>',btn('취소','close-modal')+btn('모의 운영 적용','confirm-apply','primary','data-version="'+v+'"'));break}
 case 'confirm-apply':state.active=Number(target.dataset.version);close();render();toast('모의 운영 활성 참조를 v'+state.active+'로 변경했습니다.');break;
 case 'dataset':dataset();break;
 case 'dataset-add':datasetDraft.push({id:'D'+Date.now().toString().slice(-6),input:'',expected:'',tag:''});datasetView();break;
 case 'dataset-remove':datasetDraft.splice(Number(target.dataset.index),1);datasetView();break;
 case 'dataset-publish':importErrors=[];if(!datasetDraft.length)importErrors.push('최소 한 항목이 필요합니다');datasetDraft.forEach((d,i)=>{if(!d.input.trim()||!d.expected.trim())importErrors.push((i+1)+'행 입력·기대 응답 필요')});if(new Set(datasetDraft.map(d=>d.input)).size<datasetDraft.length)importErrors.push('중복 입력을 검토하세요');if(importErrors.length){datasetView();return}state.dataset=clone(datasetDraft);state.datasetVersion++;close();render();toast('데이터셋 v'+state.datasetVersion+' 발행 · 이전 실험은 유지됩니다.');break;
 case 'evaluator':modal('평가 기준','답변 품질 v2 · 척도 0–1 · 통과 기준 0.8','<div class="prompt"><strong>루브릭</strong><p>1. 질문에 맞는 답변인가?<br>2. 정책 조건을 정확히 설명했는가?<br>3. 검색 근거와 모순되지 않는가?</p></div><p class="muted">정답·입력·응답·검색 근거를 평가기에만 전달합니다. Judge 오류는 평가 실패로 기록합니다.</p>',btn('닫기','close-modal'));break;
 case 'new-experiment':newExperiment();break;
 case 'wizard-return':wizardView();break;
 case 'wizard-dataset':modal('고정 데이터셋','v'+state.datasetVersion+' · 정답은 평가 전용','<div class="prompt">'+state.dataset.map(d=>esc(d.input)+'<br>').join('')+'</div>',btn('평가 설정으로 돌아가기','wizard-return'));break;
 case 'stop-experiment':{const exp=state.experiments.find(x=>x.id===id);exp.status='취소';exp.results.filter(r=>r.status==='대기').forEach(r=>r.status='취소');render();toast('신규 평가 배정을 멈췄습니다. 기존 결과는 유지됩니다.');break}
 case 'wizard-prev':captureWizard();wizardStep--;wizardView();break;
 case 'wizard-next':captureWizard();if(wizardStep===0&&!wizard.name){$('#wizard-error').textContent='실험 이름을 작성하세요.';return}if(wizardStep===1&&!state.dataset.length){$('#wizard-error').textContent='평가할 데이터 항목이 필요합니다.';return}if(wizardStep===2&&(!(Number(wizard.repetitions)>=1&&Number(wizard.repetitions)<=3)||!(Number(wizard.concurrency)>=1&&Number(wizard.concurrency)<=5))){$('#wizard-error').textContent='반복 1–3, 병렬도 1–5 범위를 확인하세요.';return}if(wizardStep===3)startExperiment();else{wizardStep++;wizardView()}break;
 case 'select-experiment':state.selectedExperiment=id;render();break;
 case 'compare':compare();break;
 case 'compare-item':compareItem(state.experiments.find(x=>x.id===target.dataset.a),state.experiments.find(x=>x.id===target.dataset.b),id);break;
 case 'eval-detail':{const exp=state.experiments.find(x=>x.id===target.dataset.exp);evalDetail(exp,expResults(exp).find(r=>r.id===id));break}
 case 'policy':policy();break;
 case 'toggle-policy':state.policy.active=!state.policy.active;state.policyHistory.unshift('v'+state.policy.version+' · '+(state.policy.active?'활성화':'중지'));render();toast('모의 정책을 '+(state.policy.active?'활성화':'중지')+'했습니다.');break;
 case 'save-policy':{const p=readPolicy();if(!validatePolicy(p)){$('#policy-error').textContent='이름·표본(1–100)·예산(100 이상)·통과 기준(0–1)을 확인하세요.';return}state.policy={...p,version:state.policy.version+1,active:false};state.policyHistory.unshift('v'+state.policy.version+' · 표본 '+p.sample+'% · 비활성 저장');close();render();toast('새 정책 버전 저장 · 확인 후 활성화하세요.');break}
 case 'preview-policy':{const p=readPolicy();if(!validatePolicy(p)){$('#policy-error').textContent='정책 옵션의 범위를 확인하세요.';return}modal('정책 시험 결과','운영 집계에 포함되지 않는 모의 시험입니다.','<div class="note">표본 '+p.sample+'% · '+esc(p.evaluator)+' · 기준 '+p.threshold+'</div><div class="row"><span>유효 평가</span><strong>2개</strong></div><div class="row"><span>평가 오류</span>'+badge('Judge 일시 오류 1개','amber')+'</div><div class="row"><span>모의 평가 비용</span><strong>₩12</strong></div><p class="hint">평가 오류는 0점으로 처리하지 않습니다.</p>',btn('정책 편집으로','policy')+btn('닫기','close-modal'));break}
 case 'export-runs':download('kpap-runs-demo.json',JSON.stringify(state.runs,null,2));toast('현재 실행 목록을 내려받았습니다.');break;
 }
 persist();
});
if(location.hash)state.page=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();
